/*
 * GameDistribution SDK - NEUTRALISED STUB (UBGHyper)
 * ---------------------------------------------------
 * The upstream build shipped GameDistribution's real ad SDK, which
 * domain-locks the game and plays pre-roll ads that credit a THIRD-PARTY
 * account (not UBGHyper). This stub replaces it entirely: no ads, no domain
 * check, no network calls, zero revenue leak. It fires the lifecycle events
 * the game waits on (SDK_READY, SDK_GAME_START) and resolves every ad
 * request instantly, so gameplay is never gated behind an ad.
 */
(function () {
  function ev(name) {
    try {
      var o = window.GD_OPTIONS;
      if (o && typeof o.onEvent === 'function') o.onEvent({ name: name, message: name });
    } catch (e) {}
  }
  function adResolve() {
    ev('SDK_GAME_PAUSE');
    setTimeout(function () { ev('SDK_GAME_START'); }, 30);
    return Promise.resolve();
  }
  var sdk = {
    showAd:        function () { return adResolve(); },
    preloadAd:     function () { return Promise.resolve(); },
    cancelAd:      function () { return Promise.resolve(); },
    showBanner:    function () { return adResolve(); },
    openConsole:   function () {},
    getResumeGame: function () {},
    sendRomFile:   function () {}
  };
  window.gdsdk = sdk;
  window.gdApi = sdk;
  window.GD_OPTIONS = window.GD_OPTIONS || {};
  // Announce ready + start on next tick, once the game has wired onEvent.
  setTimeout(function () { ev('SDK_READY'); ev('SDK_GAME_START'); }, 0);
})();
